// Demo for the C++ RL-FullGuard meta policy.
//
//   g++ -std=c++17 -O2 cpp/rl_full_guard_demo.cpp -o rl_full_guard_demo
//   ./rl_full_guard_demo
//
// The weights header is generated by:
//   python3 -m ipd.tools.export_full_guard_cpp \
//     --weights weights/rl_policy_weights_v5_ft_complex.json \
//     --out cpp/rl_full_guard_weights.hpp
#include <cstdio>
#include <vector>

#include "policies/rl_full_guard_policy.hpp"

int main() {
    ipd::RLFullGuardParams params;
    params.sample = false;
    ipd::RLFullGuardPolicy policy(20261024u, params);
    std::printf("features=%zu\n", policy.features({}, {}).size());
    std::vector<int> mine, theirs;
    for (int t = 0; t < 100; ++t) {
        // Probe at t=5, then keep defecting.
        const int reply = (t < 5) ? ipd::C : ipd::D;
        const int action = policy.act(t, mine, theirs);
        mine.push_back(action);
        theirs.push_back(reply);
    }
    std::printf("state=%s score=%d\n", policy.state(),
                ipd::payoff(mine.back(), theirs.back()));
    return 0;
}
